\texttt{Twist}
    =
    \left\{
    \begin{array}{l}
        \texttt{linear}=
        \left\{
        \begin{array}{l}
            x\\
            y\\
            z
        \end{array}
        \right.
        \\[4mm]
        \texttt{angular}=
        \left\{
        \begin{array}{l}
            x\\
            y\\
            z
        \end{array}
        \right.
    \end{array}
    \right.

